/* 跨表引用 */
=Sheet2!A1                    /* 引用 Sheet2 的 A1 */
='数据源'!A1                   /* 表名含特殊字符时用单引号 */

/* 跨文件引用 */
='[模具台账.xlsx]Sheet1'!A1    /* 引用另一个工作簿的数据 */

/* 定义名称后，可直接使用 */
=VLOOKUP(A1, 模具信息表, 2, FALSE)    /* 比 =VLOOKUP(A1, $A$1:$D$500, 2, FALSE) 更直观 */

/* 定义常量名称 */
税率 = 0.13                            /* 名称管理器中定义 */
=金额 * 税率                            /* 直接引用名称 */

/* 基本用法：根据模具编号查模具类型 */
=VLOOKUP(A2, $B$2:$E$500, 3, FALSE)

/* 嵌套 IFERROR：找不到时返回空值而非 #N/A */
=IFERROR(VLOOKUP(A2, $B$2:$E$500, 3, FALSE), "")

/* 多条件查找：用 & 拼接条件，辅助列或数组公式 */
=VLOOKUP(A2&B2, IF({1,0}, $A$2:$A$500&$B$2:$B$500, $C$2:$C$500), 2, FALSE)

/* 基本用法：比 VLOOKUP 更简洁 */
=XLOOKUP(A2, $B$2:$B$500, $D$2:$D$500)

/* 找不到返回空值（替代 IFERROR + VLOOKUP） */
=XLOOKUP(A2, $B$2:$B$500, $D$2:$D$500, "")

/* 从右往左查（VLOOKUP 做不到的） */
=XLOOKUP(A2, $D$2:$D$500, $B$2:$B$500)

/* 返回多列（自动溢出） */
=XLOOKUP(A2, $B$2:$B$500, $C$2:$E$500)

/* 返回最后一个匹配项（倒序搜索） */
=XLOOKUP(A2, $B$2:$B$500, $D$2:$D$500, "", 0, -1)

/* 基本用法：比 VLOOKUP 更灵活 */
=INDEX($D$2:$D$500, MATCH(A2, $B$2:$B$500, 0))

/* 从右往左查 */
=INDEX($B$2:$B$500, MATCH(A2, $D$2:$D$500, 0))

/* 二维查找（行+列交叉定位） */
=INDEX($B$2:$E$500, MATCH(A2, $A$2:$A$500, 0), MATCH(B2, $B$1:$E$1, 0))

/* 从 A1 向下偏移 3 行，向右偏移 2 列 */
=OFFSET(A1, 3, 2)                          /* 返回 C4 的值 */

/* 动态范围（配合 COUNTA 自动扩展区域） */
=OFFSET(A1, 0, 0, COUNTA(A:A), 1)          /* A 列非空单元格组成的动态范围 */

/* 配合 SUM 做动态求和 */
=SUM(OFFSET(A1, 0, 0, COUNTA(A:A), 1))     /* 对 A 列所有非空求和 */

/* 根据文本构造引用 */
=INDIRECT("A" & B1)                         /* B1=5 时，引用 A5 */

/* 跨表动态引用（表名在单元格中） */
=INDIRECT("'" & A1 & "'!B2")               /* A1="数据源" 时，引用 数据源!B2 */

/* 下拉菜单联动（二级菜单） */
=INDIRECT(A1)                               /* A1 为一级分类名称，需提前定义对应名称 */

/* 根据月份返回季度 */
=CHOOSE(MONTH(A1), 1,1,1,2,2,2,3,3,3,4,4,4)   /* 1-3月=1季度 */

/* 配合 VLOOKUP 实现动态列号 */
=VLOOKUP(A2, $B$2:$E$500, CHOOSE(B1, 1, 2, 3), FALSE)

/* 替代嵌套 IF */
=CHOOSE(MATCH(A1, {"小","中","大"}, 0), "尺寸S", "尺寸M", "尺寸L")

/* 对"挤压组"的产量求和 */
=SUMIF($B$2:$B$500, "挤压组", $C$2:$C$500)

/* 条件用单元格引用 */
=SUMIF($B$2:$B$500, F2, $C$2:$C$500)

/* 条件区域与求和区域相同（可省略第三参数） */
=SUMIF($C$2:$C$500, ">100")               /* 大于100的产量求和 */

/* 统计"合格"的记录数 */
=COUNTIF($C$2:$C$500, "合格")

/* 统计大于100的记录数 */
=COUNTIF($C$2:$C$500, ">100")

/* 统计非空记录数 */
=COUNTIF($A$2:$A$500, "<>")

/* 统计包含"模具"的记录数 */
=COUNTIF($B$2:$B$500, "*模具*")

/* 统计去重后的记录数 */
=SUMPRODUCT(1/COUNTIF($A$2:$A$500, $A$2:$A$500))

/* 计算"挤压组"的平均产量 */
=AVERAGEIF($B$2:$B$500, "挤压组", $C$2:$C$500)

/* 计算"挤压组"且产量>100的平均值 */
=AVERAGEIFS($C$2:$C$500, $B$2:$B$500, "挤压组", $C$2:$C$500, ">100")

/* 基本用法：数量 × 单价 的总和 */
=SUMPRODUCT($B$2:$B$500, $C$2:$C$500)

/* 多条件求和（类似 SUMIFS 但更灵活） */
=SUMPRODUCT(($B$2:$B$500="挤压组") * ($C$2:$C$500="合格") * $D$2:$D$500)

/* 多条件计数 */
=SUMPRODUCT(($B$2:$B$500="挤压组") * ($C$2:$C$500="合格"))

/* 加权平均 */
=SUMPRODUCT($B$2:$B$500, $C$2:$C$500) / SUM($B$2:$B$500)

/* 从模具编号提取前缀 */
=LEFT(A2, 2)                    /* "XMODWX202607260126h" → "XM" */

/* 从模具编号提取日期 */
=MID(A2, 7, 8)                  /* "XMODWX202607260126h" → "20260726" */

/* 提取最后一个字符 */
=RIGHT(A2, 1)                   /* "XMODWX202607260126h" → "h" */

/* 中文混合字符串计算字符数 */
=LEN("模具ABC")                  /* 返回 5 */
=LENB("模具ABC")                 /* 返回 7（中文2字节×2 + 英文1字节×3） */

/* 找到某字符的位置 */
=FIND("-", A2)                  /* "2026-08-09" → 5 */

/* 提取分隔符前的内容 */
=LEFT(A2, FIND("-", A2)-1)     /* "2026-08-09" → "2026" */

/* 提取分隔符后的内容 */
=RIGHT(A2, LEN(A2)-FIND("-", A2))  /* "2026-08-09" → "08-09" */

/* 替换特定字符 */
=SUBSTITUTE(A2, "h", "")        /* "XMODWX202607260126h" → "XMODWX202607260126" */

/* 只替换第2个匹配 */
=SUBSTITUTE("A-B-C-D", "-", "/", 2)   /* "A-B/C-D" */

/* 批量替换（嵌套） */
=SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(A2, "h", ""), "X", "x"), "-", "")

/* 基本拼接 */
=A2 & "-" & B2                         /* "M001-挤压组" */

/* TEXTJOIN 合并多个值（逗号分隔） */
=TEXTJOIN(",", TRUE, A2:A10)           /* "值1,值2,值3"（跳过空值） */

/* TEXTJOIN 配合 IF 做条件合并 */
=TEXTJOIN(",", TRUE, IF(B2:B10="合格", A2:A10, ""))
/* 将 B列为"合格"对应的 A列值用逗号合并 */
/* 注意：这是数组公式，Excel 2019 需 Ctrl+Shift+Enter，M365 直接回车 */

/* 合并换行显示 */
=A2 & CHAR(10) & B2                    /* 需设置单元格"自动换行" */

/* TEXT 格式化 */
=TEXT(1234.5, "#,##0.00")        /* "1,234.50" */
=TEXT(0.85, "0%")                /* "85%" */
=TEXT(DATE(2026,8,9), "yyyy-mm-dd")  /* "2026-08-09" */
=TEXT(A2, "yyyy年m月d日")         /* "2026年8月9日" */

/* TEXT 拼接（替代 CONCATENATE） */
="日期：" & TEXT(A2, "yyyy-mm-dd") & " 产量：" & TEXT(B2, "#,##0")

/* TRIM + CLEAN 清洗数据（从系统导出的数据常有隐藏字符） */
=TRIM(CLEAN(A2))

/* 数值转文本（避免被识别为数字） */
="" & A2                         /* 或 =A2 & "" */

/* Excel 365 可以用 TEXTSPLIT */
=TEXTSPLIT(A2, ",")              /* 按逗号分割 */
=TEXTSPLIT(A2, {"-", " "})       /* 按多个分隔符分割 */
=TEXTSPLIT(A2, , CHAR(10))       /* 按换行符分割（按行） */

/* 旧版本：用 LEFT/MID/RIGHT + FIND 组合 */
/* 提取第一个逗号前的值 */
=LEFT(A2, FIND(",", A2)-1)

/* 提取两个逗号之间的值 */
=MID(A2, FIND(",", A2)+1, FIND(",", A2, FIND(",", A2)+1) - FIND(",", A2) - 1)

/* 原理：计算逗号个数 + 1 = 项数 */
/* 方法1：LEN + SUBSTITUTE（推荐，全版本适用） */
=LEN(A2) - LEN(SUBSTITUTE(A2, ",", "")) + 1

/* 方法2：处理空值情况 */
=IF(A2="", 0, LEN(A2) - LEN(SUBSTITUTE(A2, ",", "")) + 1)

/* 示例："534299,516655,543618" → 3 */

/* 计算两个日期间隔 */
=DATEDIF(A2, B2, "Y") & "年" & DATEDIF(A2, B2, "YM") & "月" & DATEDIF(A2, B2, "MD") & "日"

/* 计算模具上机到现在的天数 */
=DATEDIF(A2, TODAY(), "D")

/* 获取本月月末 */
=EOMONTH(TODAY(), 0)             /* 如 2026/8/31 */

/* 获取上月月末 */
=EOMONTH(TODAY(), -1)            /* 如 2026/7/31 */

/* 获取下月月初 */
=EOMONTH(TODAY(), 0) + 1        /* 如 2026/9/1 */

/* 计算本月工作日天数 */
=NETWORKDAYS(EOMONTH(TODAY(), -1)+1, EOMONTH(TODAY(), 0))

/* 自定义周末（如周日休息，参数11=周日休息） */
=NETWORKDAYS.INTL(A2, B2, 11)

/* 昨天7:00 到 今天7:00 的时间范围判断 */
=(A2 >= DATE(YEAR(TODAY()-1), MONTH(TODAY()-1), DAY(TODAY()-1)) + TIME(7,0,0))
*
(A2 < DATE(YEAR(TODAY()), MONTH(TODAY()), DAY(TODAY())) + TIME(7,0,0))

/* 本周一日期 */
=TODAY() - WEEKDAY(TODAY(), 2) + 1

/* 本月第一天 */
=EOMONTH(TODAY(), -1) + 1

/* 本月最后一天 */
=EOMONTH(TODAY(), 0)

/* 本季度第一天 */
=DATE(YEAR(TODAY()), INT((MONTH(TODAY())-1)/3)*3+1, 1)

/* 本年度第一天 */
=DATE(YEAR(TODAY()), 1, 1)

/* 基本用法 */
=IF(A2 >= 60, "合格", "不合格")

/* 嵌套 IF（最多64层，但不建议超过3层） */
=IF(A2 >= 90, "优秀", IF(A2 >= 80, "良好", IF(A2 >= 60, "及格", "不及格")))

/* IF 与 AND/OR 组合 */
=IF(AND(A2 >= 60, B2 >= 60), "全部合格", "有不合格")

/* 空值判断 */
=IF(A2="", "未填", A2 * 2)

/* 替代嵌套 IF */
=IFS(A2 >= 90, "优秀", A2 >= 80, "良好", A2 >= 60, "及格", TRUE, "不及格")
/* 最后的 TRUE 相当于 else */

/* 模具状态码转中文 */
=SWITCH(A2, "10", "在架", "219", "待上架", "421", "待修模", "422", "待返修", "300", "报废", "未知状态")

/* 比嵌套 IF 更清晰 */

/* 判断是否在有效范围内 */
=AND(A2 >= 100, A2 <= 500)

/* 判断是否满足任一条件 */
=OR(A2 = "紧急", B2 > 1000)

/* 配合 IF 使用 */
=IF(AND(A2 <> "", B2 <> ""), A2 * B2, 0)

/* VLOOKUP 找不到时返回空值 */
=IFERROR(VLOOKUP(A2, $B$2:$D$500, 3, FALSE), "未找到")

/* 除法防除零 */
=IFERROR(A2/B2, 0)

/* 只处理 #N/A，其他错误照常显示 */
=IFNA(VLOOKUP(A2, $B$2:$D$500, 3, FALSE), "未找到")

/* 四舍五入到2位小数 */
=ROUND(A2, 2)                  /* 3.14159 → 3.14 */

/* 向上取整到整数 */
=ROUNDUP(A2, 0)                /* 3.1 → 4 */

/* 向上取到10的倍数 */
=CEILING(A2, 10)               /* 23 → 30 */

/* 向下取到10的倍数 */
=FLOOR(A2, 10)                 /* 23 → 20 */

/* INT vs TRUNC 对负数的区别 */
=INT(-3.5)                     /* -4（向下取整） */
=TRUNC(-3.5)                   /* -3（直接截断） */

/* 条件排名 */
=RANK(A2, $A$2:$A$500)         /* 降序排名（默认） */
=RANK(A2, $A$2:$A$500, 1)      /* 升序排名 */

/* 去除最大最小值后取平均（裁判打分场景） */
=(SUM(A2:A10) - MAX(A2:A10) - MIN(A2:A10)) / (COUNT(A2:A10) - 2)

/* 也可以用 TRIMMEAN 函数 */
=TRIMMEAN(A2:A10, 2/COUNT(A2:A10))    /* 去掉头尾各1个 */

/* 统计唯一值个数 */
=SUMPRODUCT(($A$2:$A$500<>"") / COUNTIF($A$2:$A$500, $A$2:$A$500&""))

/* 判断奇偶 */
=IF(MOD(A2, 2) = 0, "偶数", "奇数")

/* 每页固定行数的分组（如每10行一组） */
=CEILING(ROW()-1, 10) / 10     /* 第1-10行=1, 第11-20行=2, ... */

/* 计算圆面积（如模具面积） */
=PI() * (A2/2)^2                /* A2=直径 */

/* 筛选"挤压组"的全部记录 */
=FILTER(A2:E500, B2:B500="挤压组")

/* 多条件筛选（AND） */
=FILTER(A2:E500, (B2:B500="挤压组") * (C2:C500="合格"))

/* 多条件筛选（OR） */
=FILTER(A2:E500, (B2:B500="挤压组") + (B2:B500="包装组"))

/* 筛选不到时返回提示 */
=FILTER(A2:E500, B2:B500="挤压组", "无匹配数据")

/* 按第3列降序排序 */
=SORT(A2:E500, 3, -1)

/* 多列排序：先按组别升序，再按产量降序 */
=SORT(A2:E500, {2,4}, {1,-1})

/* 按另一列排序（不改变原始列顺序） */
=SORTBY(A2:B500, C2:C500, -1)

/* 提取唯一值 */
=UNIQUE(A2:A500)               /* 去重后的模具编号列表 */

/* 提取两列组合的唯一值 */
=UNIQUE(A2:B500)

/* 只提取出现一次的值（非重复项） */
=UNIQUE(A2:A500, FALSE, TRUE)

/* 筛选+排序+去重 一气呵成 */
=SORT(UNIQUE(FILTER(A2:B500, C2:C500="合格")))

/* XLOOKUP 返回多列 */
=XLOOKUP(A2, B2:B500, C2:E500)   /* 自动溢出3列 */

/* 动态下拉菜单（唯一值列表） */
=UNIQUE(A2:A500)                 /* 放在数据验证来源中 */

/* 模式1：IFERROR 统一处理 */
=IFERROR(A2/B2, 0)

/* 模式2：IFNA 只处理 #N/A（调试友好） */
=IFNA(VLOOKUP(A2, B2:D500, 3, FALSE), "未找到")

/* 模式3：IF + ISERROR 分级处理 */
=IF(ISERROR(A2/B2), "计算错误", A2/B2)

/* 模式4：ERROR.TYPE 判断错误类型 */
=IF(ERROR.TYPE(A2) = 2, "除零错误", IF(ERROR.TYPE(A2) = 7, "找不到值", A2))

/* 批量检查数据有效性 */
=IF(ISBLANK(A2), "空值", IF(ISTEXT(A2), "文本", IF(ISNUMBER(A2), "数值", "其他")))

/* 1. F9 键：选中公式的一部分按 F9 可查看计算结果 */
